/**
  * Builds queue-ready parat_bridge system notifications for a
  * connection lifecycle event.                                                                                                                                    
  *
  * Input:                                                                                                                                                         
  *   msg.payload           = connection object                                                                                                                  
  *   msg.event             = "opprettet" | "stopped" | "lost"                                                                                                     
  *   msg.failed_identifier = (only for "lost") identifier of the side                                                                                           
  *                           whose outgoing message could not be delivered                                                                                        
  *                                                                                                                                                                
  * Output: array-of-array of queue-ready msgs (one per direction).
  */
const connection = msg.payload;
const event = msg.event;

if (!connection || !connection.clients) return null;

const clients = Object.values(connection.clients);
if (clients.length !== 2) return null;

const bridge_source = {
    client_system: "parat_bridge",
    name: "parat_bridge",
    identifier: "parat_bridge"
};

const failed_identifier = msg.failed_identifier;
const failed_client = failed_identifier
    ? clients.find(c => c.identifier === failed_identifier)
    : null;
const failed_name = failed_client
    ? (failed_client.name || failed_client.client_system)
    : null;

const phrase_for = (target) => {
    const other = clients.find(c => c.identifier !== target.identifier) || clients[0];
    const other_name = other.name || other.client_system;

    if (event === "opprettet") {
        return `🛜 Tilkobling mot ${other_name} er opprettet.`;
    }

    if (event === "stopped") {
        return `❌ Tilkobling til ${other_name} er stoppet - videre meldinger vil ikke bli sendt.`;
    }

    if (event === "lost") {
        if (failed_identifier && target.identifier === failed_identifier) {
            return `❌ Tilkobling til ${other_name} er mistet - din siste melding er ikke sendt.`;
        }
        return `❌ Tilkobling til ${other_name} er mistet og har problemer - videre meldinger vil ikke bli levert før tilkoblingen er gjenopprettet.`;
    }   

    return `❌ Tilkobling til ${other_name} er mistet.`;  // fallback                                                                                             
};

const now = Date.now();
const rand = () => Math.random().toString(36).substr(2, 6);

const notifications = clients.map(target => ({
    topic: "new_message",
    entry: {
        id: `pb-conn-${event}-${now}-${rand()}`,
        text: phrase_for(target),
        timestamp: now,
        author: "System-melding",
        labels: [],
        metadata: {
            source: bridge_source,
            target: target,
            connection_name: connection.name,
            files: null
        }
    }
}));

return [notifications];
